105	fn decide(args: ReleasePrDecideArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
106	    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_arg_as("snapshot", &args.snapshot)?;
107	    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
108	    let repository =
109	        GitHubRepository::parse(&args.repository).map_err(|_error| ReleasePrDecisionError::InvalidRepository {
110	            repository: args.repository.clone(),
111	        })?;
112	    let config = ReleasePrConfigV1::new(repository, args.base_branch, args.release_branch)?;
113	
114	    let runner = CliCommandRunner;
115	    let workspace = load_workspace(global, &runner)?;
116	    let inference = crate::workspace::select_inference();
117	    let status = status(&workspace, &inference, &StatusOptions::default())?;
118	    let decision = ReleasePrDecisionV2::derive(status.has_changesets, &config, &snapshot)?;
119	
120	    match global.format {
121	        OutputFormat::Json => emit_report(
122	            &mut std::io::stdout(),
123	            &ReleasePrDecideReport { decision },
124	            global.dry_run,
125	        )?,
126	        OutputFormat::Text => render_decision(&decision)?,
127	    }
128	    Ok(ExitCode::SUCCESS)
129	}
