131	fn commit_plan(args: ReleasePrCommitPlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
132	    let base_commit = CommitSha::parse(&args.base_commit)?;
133	
134	    let start = dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
135	        source,
136	        path: Some(global.cwd.clone()),
137	    })?;
138	    let runner = CliCommandRunner;
139	    let git = GitAccess::new(&start, &runner);
140	    let changes = git.staged_changes_since(&base_commit)?;
141	    let plan = ReleasePrCommitPlanV1::from_changes(base_commit, args.message, changes)?;
142	
143	    match args.out {
144	        Some(path) => {
145	            let permit =
146	                ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or(CliError::ReleasePrCommitPlanDryRun)?;
147	            let content = serde_json::to_string_pretty(&plan).expect("commit plan serializes") + "\n";
148	            callisto_model::atomic::atomic_write(&path, &content, &permit).map_err(|source| CliError::Io {
149	                source,
150	                path: Some(path),
151	            })?;
152	        }
153	        None => emit_report(
154	            &mut std::io::stdout(),
155	            &ReleasePrCommitPlanReport { plan },
156	            global.dry_run,
157	        )?,
158	    }
159	    Ok(ExitCode::SUCCESS)
160	}
