162	fn render_decision(decision: &ReleasePrDecisionV2) -> Result<(), CliError> {
163	    match &decision.action {
164	        ReleasePrActionV2::Noop { reason } => emit_line(&format!("release PR: no-op ({reason:?})"))?,
165	        ReleasePrActionV2::Create { branch, staging_branch } => {
166	            emit_line(&format!("release PR: create {branch} (staging {staging_branch})"))?
167	        }
168	        ReleasePrActionV2::Update {
169	            pull_request_number,
170	            branch,
171	            expected_head_commit,
172	            staging_branch,
173	        } => emit_line(&format!(
174	            "release PR: update #{pull_request_number} ({branch}, expected head {}, staging {staging_branch})",
175	            expected_head_commit.as_str()
176	        ))?,
177	        _ => emit_line("release PR: unsupported decision")?,
178	    }
179	    Ok(())
180	}
