 34	/// Reads `flag`'s argument (file, inline JSON, or `-` for stdin) as an unvalidated wire
 35	/// value. Kept separate from the domain type's own validating constructor so a JSON parse
 36	/// failure (`E281`) and a domain validation failure (its own typed `E1xx` code) are never
 37	/// folded into one generic error.
 38	fn read_json_arg_as<T: serde::de::DeserializeOwned>(flag: &'static str, arg: &str) -> Result<T, CliError> {
 39	    let text = read_json_arg(arg)?;
 40	    serde_json::from_str(&text).map_err(|error| CliError::ReleasePrArgJsonInvalid {
 41	        flag,
 42	        detail: error.to_string(),
 43	    })
 44	}
