 48	struct ReleasePrDecisionInput {
 49	    schema_version: u8,
 50	    config: ReleasePrConfigWireV1,
 51	    snapshot: ReleasePrSnapshotWireV2,
 52	    action: ReleasePrActionV2,
 53	    #[serde(default, deserialize_with = "deserialize_present")]
 54	    command: Option<String>,
 55	    #[serde(default, deserialize_with = "deserialize_present")]
 56	    dry_run: Option<bool>,
 57	}
 58	
 59	// Missing report metadata is allowed, but present null values are not.
 60	fn deserialize_present<'de, D, T>(deserializer: D) -> Result<Option<T>, D::Error>
 61	where
 62	    D: serde::Deserializer<'de>,
 63	    T: serde::Deserialize<'de>,
 64	{
 65	    T::deserialize(deserializer).map(Some)
 66	}
