 68	fn read_decision_arg(arg: &str) -> Result<ReleasePrDecisionWireV2, CliError> {
 69	    let input: ReleasePrDecisionInput = read_json_arg_as("decision", arg)?;
 70	    match (&input.command, input.dry_run) {
 71	        (None, None) => {}
 72	        (Some(command), Some(_)) if command == <ReleasePrDecideReport as callisto_model::Report>::COMMAND => {}
 73	        _ => {
 74	            return Err(CliError::ReleasePrArgJsonInvalid {
 75	                flag: "decision",
 76	                detail: "report metadata must include command=\"release-pr decide\" and a boolean dryRun".into(),
 77	            });
 78	        }
 79	    }
 80	    Ok(ReleasePrDecisionWireV2 {
 81	        schema_version: input.schema_version,
 82	        config: input.config,
 83	        snapshot: input.snapshot,
 84	        action: input.action,
 85	    })
 86	}
